{
  "nodes": [
    {
      "id": "monster_undead",
      "type": "monster",
      "name": "不死族",
      "importance": 1.0,
      "properties": {
        "description": "一种怪物类别，包含骷髅、僵尸、吸血鬼等死后复生的生物。"
      }
    },
    {
      "id": "monster_skeleton",
      "type": "monster",
      "name": "骷髅兵",
      "importance": 0.6,
      "properties": {
        "description": "钢铁等级不死族怪物，生命值18，擅长使用单手剑，具有再生和黑暗视觉能力。"
      }
    },
    {
      "id": "monster_zombie",
      "type": "monster",
      "name": "僵尸",
      "importance": 0.6,
      "properties": {
        "description": "黑曜石等级不死族怪物，生命值25，具有格斗和强韧能力。"
      }
    },
    {
      "id": "monster_mummy",
      "type": "monster",
      "name": "木乃伊",
      "importance": 0.7,
      "properties": {
        "description": "翠玉石等级不死族怪物，生命值45，具有咒病和强韧能力。"
      }
    },
    {
      "id": "monster_ghoul",
      "type": "monster",
      "name": "食尸鬼",
      "importance": 0.7,
      "properties": {
        "description": "青玉石等级不死族怪物，生命值32，拥有麻痹爪技能。"
      }
    },
    {
      "id": "monster_vampire",
      "type": "monster",
      "name": "吸血鬼",
      "importance": 0.9,
      "properties": {
        "description": "白银等级不死族怪物，生命值150，全属性较高，擅长细剑与魔术，拥有魅惑之眼。"
      }
    },
    {
      "id": "monster_ghost",
      "type": "monster",
      "name": "幽灵",
      "importance": 0.7,
      "properties": {
        "description": "青玉石等级不死族怪物，生命值20，具有极高的物理韧性（非实体）和附身能力。"
      }
    },
    {
      "id": "monster_crypt_horror",
      "type": "monster",
      "name": "墓穴恶鬼",
      "importance": 0.7,
      "properties": {
        "description": "翠玉石等级不死族怪物，生命值90，拥有巨力爪击和恐惧咆哮。"
      }
    },
    {
      "id": "monster_grave_guard",
      "type": "monster",
      "name": "荒坟守卫",
      "importance": 0.8,
      "properties": {
        "description": "红玉石等级不死族怪物，生命值65，装备重甲和双手斧，具有不屈特性。"
      }
    },
    {
      "id": "monster_black_knight",
      "type": "monster",
      "name": "黑骑士",
      "importance": 0.8,
      "properties": {
        "description": "青铜等级不死族怪物，生命值70，骑乘梦魇坐骑，擅长骑枪冲锋。"
      }
    },
    {
      "id": "monster_banshee",
      "type": "monster",
      "name": "女妖",
      "importance": 0.8,
      "properties": {
        "description": "青铜等级不死族怪物，生命值40，非实体生物，拥有破甲哀嚎和幽魂之触。"
      }
    },
    {
      "id": "monster_wight",
      "type": "monster",
      "name": "尸妖",
      "importance": 0.9,
      "properties": {
        "description": "白银等级不死族怪物，生命值180，能统帅僵尸与骷髅，具有瘟疫爪击和尸体爆破能力。"
      }
    },
    {
      "id": "monster_black_coach",
      "type": "monster",
      "name": "黑马车",
      "importance": 0.9,
      "properties": {
        "description": "白银等级（高阶）不死族怪物，生命值250，属于魔法构装体，能吸收灵魂。"
      }
    },
    {
      "id": "monster_blood_knight",
      "type": "monster",
      "name": "血骑士",
      "importance": 0.9,
      "properties": {
        "description": "准黄金等级不死族怪物，生命值160，装备血龙甲，骑乘梦魇战马，处于嗜血狂怒状态。"
      }
    },
    {
      "id": "monster_blood_knight_captain",
      "type": "monster",
      "name": "血骑士长",
      "importance": 1.0,
      "properties": {
        "description": "黄金等级不死族怪物，生命值240，装备血龙王甲，拥有毁灭风暴和黑暗庇护能力。"
      }
    },
    {
      "id": "monster_terrorgheist",
      "type": "monster",
      "name": "惊惧兽",
      "importance": 1.0,
      "properties": {
        "description": "黄金等级（高阶）不死族怪物，生命值380，重型巨兽单位，拥有恐怖再生和破甲巨爪。"
      }
    },
    {
      "id": "monster_vargheist",
      "type": "monster",
      "name": "恐怖天鬼",
      "importance": 1.0,
      "properties": {
        "description": "黄金等级（高阶）不死族怪物，生命值300，飞行单位，擅长刺杀俯冲和死亡尖啸。"
      }
    }
  ],
