{
  "nodes": [
    {
      "id": "monster_demon",
      "type": "monster",
      "name": "魔神",
      "importance": 0.9,
      "properties": {
        "description": "一种强大的怪物种族，包含下位、上位、魔神将及梦魔等多种形态。"
      }
    },
    {
      "id": "monster_lower_demon",
      "type": "monster",
      "name": "下位魔神",
      "importance": 0.6,
      "properties": {
        "description": "翠玉等级的魔神，生命值55，擅长使用长枪和初级魔术，拥有飞行和多方位视觉能力。",
        "rank": "翠玉等级"
      }
    },
    {
      "id": "monster_upper_demon",
      "type": "monster",
      "name": "上位魔神",
      "importance": 0.7,
      "properties": {
        "description": "青铜等级的魔神，生命值90，擅长双手剑和中级魔术，具备再生、装甲、飞行及多方位视觉能力。",
        "rank": "青铜等级"
      }
    },
    {
      "id": "monster_demon_general",
      "type": "monster",
      "name": "魔神将",
      "importance": 0.8,
      "properties": {
        "description": "黄金等级的高阶魔神，生命值250，拥有极高的各项属性，擅长上级魔术和长枪战斗。",
        "rank": "黄金等级"
      }
    },
    {
      "id": "monster_succubus_incubus",
      "type": "monster",
      "name": "魅魔/梦魔",
      "importance": 0.7,
      "properties": {
        "description": "青玉等级的魔神，女性称为魅魔，男性称为梦魔。擅长变形、魅惑、梦境入侵及精气榨取。",
        "rank": "青玉等级"
      }
    }
  ],
  "edges": [
    {
      "id": "edge_monster_lower_demon_monster_demon_related_to",
      "source": "monster_lower_demon",
      "target": "monster_demon",
      "relation": "related_to",
      "weight": 1.0,
      "properties": {
        "description": "下位魔神属于魔神的一种"
      }
    },
    {
