        "description": "上位魔神属于魔神的一种"
      }
    },
    {
      "id": "edge_monster_demon_general_monster_demon_related_to",
      "source": "monster_demon_general",
      "target": "monster_demon",
      "relation": "related_to",
      "weight": 1.0,
      "properties": {
        "description": "魔神将属于魔神的高阶形态"
      }
    },
    {
      "id": "edge_monster_succubus_incubus_monster_demon_related_to",
