      "weight": 1.0,
      "properties": {
        "description": "魅魔与梦魔属于魔神的一种"
      }
    }
  ]
}

{
  "nodes": [
    {
      "id": "race_demi_human",
      "type": "race",
      "name": "亚人类",
      "importance": 0.8,
      "properties": {
        "description": "一种生物分类，包含暗人、鹰身女妖、蜥蜴人等具有人类特征的非人类种族。"
      }
    },
    {
      "id": "race_dragon",
      "type": "race",
      "name": "龙族",
      "importance": 0.9,
      "properties": {
        "description": "强大的生物种族，包含幼龙等，通常具有极高的物理和魔法抗性。"
      }
    },
    {
      "id": "monster_dark_elf",
      "type": "monster",
      "name": "暗人",
      "importance": 0.6,
      "properties": {
        "description": "青玉石等级亚人类怪物。生命值35，擅长细剑、魔术（初级）与斥候技能，拥有黑暗视觉和毒知识。"
      }
    },
    {
      "id": "monster_harpy",
      "type": "monster",
      "name": "鹰身女妖",
      "importance": 0.5,
      "properties": {
        "description": "钢铁等级亚人类怪物。生命值18，具备飞行能力和特殊的歌声技能，擅长格斗。"
      }
    },
    {
      "id": "monster_lizardman",
      "type": "monster",
      "name": "蜥蜴人",
      "importance": 0.6,
      "properties": {
        "description": "青玉石等级亚人类怪物。生命值40，拥有鳞片皮肤，擅长使用战斧或短枪，具备龙祭司（初级）能力。"
      }
    },
    {
      "id": "monster_young_dragon",
      "type": "monster",
      "name": "幼龙",
      "importance": 0.8,
      "properties": {
        "description": "黄金等级龙族怪物。生命值高达300，拥有极高的力量（12）和魔力（8），具备龙息、再生（中级）及高额物理/魔法韧性。"
      }
    }
  ],
  "edges": [
    {
      "id": "edge_monster_dark_elf_race_demi_human_related_to",
      "source": "monster_dark_elf",
      "target": "race_demi_human",
      "relation": "related_to",
