        "description": "属于亚人类分类"
      }
    },
    {
      "id": "edge_monster_lizardman_race_demi_human_related_to",
      "source": "monster_lizardman",
      "target": "race_demi_human",
      "relation": "related_to",
      "weight": 1.0,
      "properties": {
        "description": "属于亚人类分类"
      }
    },
    {
      "id": "edge_monster_young_dragon_race_dragon_related_to",
      "source": "monster_young_dragon",
      "target": "race_dragon",
      "relation": "related_to",
      "weight": 1.0,
      "properties": {
        "description": "属于龙族分类"
      }
    }
  ]
}

{
  "nodes": [
    {
      "id": "concept_primordial_monster",
      "type": "concept",
      "name": "神代怪物",
      "importance": 1.0,
      "properties": {
        "description": "诸神直接行于大地的时代所存在的、作为现存魔物始祖的强大存在，接近于行走的神罚或失控的创世之力。"
      }
    },
    {
      "id": "monster_hecatoncheires",
      "type": "monster",
      "name": "百臂巨人",
      "importance": 0.9,
      "properties": {
        "aliases": "巨人族之祖, 世界之基石, The Hundred-Handed One",
        "description": "巨人族之祖，秩序诞生前的混沌化身，由无数执矛巨臂构成的活体山脉。",
        "threat_level": "宏大叙事级灾害"
      }
    },
    {
      "id": "monster_goblin_overlord",
      "type": "monster",
      "name": "哥布林大君",
      "importance": 0.9,
      "properties": {
        "aliases": "最初的阴影, The First Trickster",
        "description": "神代哥布林的始祖，体型不定、能够融入阴影的强大精怪，代表纯粹的恶意与狡诈。",
        "threat_level": "区域级威胁 (潜力可达宏大叙事级)"
      }
    },
    {
      "id": "monster_progenitor_slime",
      "type": "monster",
      "name": "原初黏体",
      "importance": 0.9,
      "properties": {
        "aliases": "阿米巴之海, The All-Consuming Broth",
        "description": "拥有集体意识的原生质海洋，神明创造生命时失败的初版，能吞噬并解析一切。",
        "threat_level": "宏大叙事级灾害"
      }
    },
    {
      "id": "monster_progenitor_wyrm",
      "type": "monster",
      "name": "龙之始祖",
      "importance": 0.9,
      "properties": {
        "aliases": "天灾化身, Incarnate Cataclysm",
        "description": "所有龙类的共同祖先，世界创伤的具象化，每一次现身都是一场天灾。",
        "threat_level": "宏大叙事级灾害"
      }
    },
    {
      "id": "monster_weaver_of_thousand_maws",
      "type": "monster",
      "name": "千喉之织者",
      "importance": 0.9,
      "properties": {
        "aliases": "万物分解者, The Decomposer",
        "description": "虫类与蛛类怪物的始祖，由无数扭曲肢体构成的集合体，代表无尽的饥饿。",
        "threat_level": "宏大叙事级灾害"
      }
    },
    {
      "id": "monster_echo_of_stillness",
      "type": "monster",
      "name": "寂静回响",
      "importance": 0.9,
      "properties": {
        "aliases": "原初法则, The First Law",
        "description": "所有构造体的概念祖先，代表永恒不变的法则，对运动和变化抱有敌意。",
        "threat_level": "宏大叙事级灾害"
      }
    },
    {
      "id": "monster_troll",
      "type": "monster",
      "name": "巨魔",
      "importance": 0.5,
      "properties": {
        "description": "百臂巨人的劣化后裔之一。"
      }
    },
    {
      "id": "monster_ogre",
      "type": "monster",
      "name": "食人魔",
      "importance": 0.5,
      "properties": {
        "description": "百臂巨人的劣化后裔之一。"
      }
    },
    {
      "id": "monster_goblin",
      "type": "monster",
      "name": "哥布林",
      "importance": 0.5,
      "properties": {
        "description": "哥布林大君的拙劣模仿者。"
      }
    },
    {
      "id": "monster_goblin_champion",
      "type": "monster",
      "name": "哥布林英雄",
      "importance": 0.6,
      "properties": {
        "description": "哥布林血脉中偶然出现的微弱返祖现象。"
      }
    },
    {
      "id": "monster_slime",
      "type": "monster",
      "name": "史莱姆",
      "importance": 0.4,
      "properties": {
        "description": "原初黏体溅出后因环境而劣化的微小碎片。"
      }
    },
    {
      "id": "monster_dragon",
      "type": "monster",
      "name": "龙族",
      "importance": 0.7,
      "properties": {
        "description": "继承了龙之始祖天灾权能碎片的后裔。"
      }
