{
  "nodes": [
    {
      "id": "concept_necrophages",
      "type": "concept",
      "name": "食尸生物",
      "importance": 0.8,
      "properties": {
        "description": "怪物图鉴分类，包含食尸魔、水鬼等以尸体为食或与死亡相关的生物。"
      }
    },
    {
      "id": "monster_phougefiend",
      "type": "monster",
      "name": "食尸魔",
      "importance": 0.6,
      "properties": {
        "description": "白瓷等级怪物。佝偻且如无皮犬和人被粗暴地结合的没有毛发的生物，周身散发恶臭与尸瘴，通常四肢着地行动。",
        "skills": "撕咬, 利爪, 食尸魔恶臭, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_alphougefiend",
      "type": "monster",
      "name": "巨食尸魔",
      "importance": 0.7,
      "properties": {
        "description": "青玉等级怪物。体型庞大，通常站立行动，可以拾起树干等巨大条状物作为武器，能通过吞食尸体恢复伤口。",
        "skills": "尸鬼重击, 有毒爪牙, 食尸魔恶臭, 食尸恢复, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_phougefiend_hag",
      "type": "monster",
      "name": "墓穴女巫",
      "importance": 0.75,
      "properties": {
        "description": "红玉等级怪物。变异的雌性食尸魔，形象类似长有长发并直立行走的食尸魔，通常独自居住，有时会领导食尸魔。",
        "skills": "长舌撕裂, 墓穴女巫, 有毒爪牙, 魔术师, 食尸魔恶臭, 食尸恢复, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_drowner",
      "type": "monster",
      "name": "水鬼",
      "importance": 0.5,
      "properties": {
        "description": "黑曜等级怪物。擅长水下行动，在完全无水的地面环境中行动困难。",
        "skills": "有毒爪牙, 水下行动, 陆行困难, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_water_hag",
      "type": "monster",
      "name": "沼泽鬼婆",
      "importance": 0.7,
      "properties": {
        "description": "翠玉等级怪物。变异的雌性水鬼，具有青色皮肤和如同水草般的头发，能投掷泥团并驱使多名水鬼。",
        "skills": "有毒爪牙, 水下行动, 泥泞投掷, 沼泽鬼婆, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_rotfiend",
      "type": "monster",
      "name": "食腐魔",
      "importance": 0.65,
      "properties": {
        "description": "青玉等级怪物。形似被剥了皮的腐烂尸体，散逸的毒雾能降低体力，濒死时会发生剧烈自爆。",
        "skills": "有毒爪牙, 食腐魔瘴气, 腐瘴自爆, 食尸恢复, 毒素抗性, 黑暗视觉"
      }
    },
    {
      "id": "monster_foglet",
      "type": "monster",
      "name": "小雾妖",
      "importance": 0.7,
      "properties": {
        "description": "红玉等级怪物。具有类似精灵的耳朵和犬般的脸，能制造浓雾和幻象，在雾中可转化为虚体形态。",
        "skills": "有毒爪牙, 制造浓雾, 迷雾幻象, 雾妖遁术, 毒素抗性, 黑暗视觉"
      }
    }
  ],
