      }
    },
    {
      "id": "character_cow_girl",
      "type": "character",
      "name": "牧牛妹",
      "importance": 0.9,
      "properties": {
        "description": "哥布林杀手的青梅竹马，在失去家人后被舅舅收养。在牧场与哥布林杀手重逢，并为他提供了居住的地方。"
      }
