{
  "nodes": [
    {
      "id": "concept_automated_check_system",
      "type": "concept",
      "name": "自动化判定系统",
      "importance": 1.0,
      "properties": {
        "description": "一个由世界规则和AI共同驱动的、无需GM的自动化判定系统，负责处理角色所有结果不确定的行为。"
      }
    },
    {
      "id": "concept_attribute_strength",
      "type": "concept",
      "name": "力量",
      "importance": 0.8,
      "properties": {
        "description": "展现纯粹的肉体力量，强调brute-force解决方案。",
        "applications": "推开障碍物, 挣脱束缚, 破坏物体"
      }
    },
    {
      "id": "concept_attribute_agility",
      "type": "concept",
      "name": "敏捷",
      "importance": 0.8,
      "properties": {
        "description": "考验身体的灵活性与反应速度，强调精准控制与快速反应。",
        "applications": "躲避陷阱, 在狭窄处移动, 潜行"
      }
    },
    {
      "id": "concept_attribute_perception",
      "type": "concept",
      "name": "感知",
      "importance": 0.8,
      "properties": {
        "description": "测试五感与直觉的敏锐度，强调对环境细节的捕捉能力。",
        "applications": "发现隐藏的敌人或陷阱, 追踪痕迹, 察言管色"
      }
    },
    {
      "id": "concept_attribute_knowledge",
      "type": "concept",
      "name": "知识",
      "importance": 0.8,
      "properties": {
        "description": "衡量角色的学识与记忆力，强调智力与信息的价值。",
        "applications": "解读古代文字, 识别魔法物品, 回忆怪物弱点"
      }
    },
    {
      "id": "concept_attribute_charm",
      "type": "concept",
      "name": "魅力",
      "importance": 0.8,
      "properties": {
        "description": "影响他人态度的社交能力，强调沟通与人际交往技巧。",
        "applications": "说服守卫, 交易中砍价, 安抚受惊的平民"
      }
    },
    {
      "id": "concept_attribute_faith",
      "type": "concept",
      "name": "信仰力",
      "importance": 0.8,
      "properties": {
        "description": "施展神迹和体现与神明的连接，强调精神信仰的力量。",
        "applications": "祈祷获得神迹, 抵抗邪恶力量, 坚定信仰"
      }
    },
    {
      "id": "concept_attribute_magic",
      "type": "concept",
      "name": "魔力",
      "importance": 0.8,
      "properties": {
        "description": "施展魔法和衡量魔力储备，强调感知和操控魔力。",
        "applications": "施展真言咒文或精灵术，感知魔力，操控魔力"
      }
    },
    {
      "id": "concept_result_critical_success",
      "type": "concept",
      "name": "大成功",
      "importance": 0.7,
      "properties": {
        "trigger": "2d6掷骰结果为(6,6)=12",
        "description": "产生超乎想象的完美结果，并可能带来意想不到的正面效应。"
      }
    },
    {
      "id": "concept_result_critical_failure",
      "type": "concept",
      "name": "大失败",
      "importance": 0.7,
      "properties": {
        "trigger": "2d6掷骰结果为(1,1)=2",
        "description": "造成了灾难性的后果，情况比单纯的失败要糟糕得多。"
      }
    },
    {
      "id": "concept_difficulty_routine",
      "type": "concept",
      "name": "常规难度",
      "importance": 0.6,
      "properties": {
        "target_value": "自动成功",
        "description": "无需判定的日常行为，或当角色能力远超挑战时。"
      }
    },
    {
      "id": "concept_difficulty_normal",
      "type": "concept",
      "name": "普通难度",
      "importance": 0.6,
      "properties": {
        "target_value": "9",
        "description": "标准难度的挑战，需要集中注意力，普通人成功与失败的可能性并存。"
      }
    },
    {
      "id": "concept_difficulty_epic",
      "type": "concept",
      "name": "史诗难度",
      "importance": 0.6,
      "properties": {
        "target_value": "20",
        "description": "凡人几乎无法完成的壮举。只有超凡存在才有望一试。"
      }
