      }
    },
    {
      "id": "deity_earth_mother",
      "type": "deity",
      "name": "地母神",
      "importance": 1.0,
      "properties": {
        "description": "秩序五柱神之一。象征羽翼女性，掌管农业、丰收、慈悲、修复、性爱。信徒多为农民与服务者，神殿兼具孤儿院功能。"
      }
    },
    {
      "id": "deity_supreme_god",
      "type": "deity",
      "name": "至高神",
