      "importance": 0.95,
      "properties": {
        "description": "外神。象征绿色瞳孔，唯一直接干涉棋子主动撕毁“黄金约定”的存在，赋予扭曲的知识，侵蚀自由意志。"
      }
    },
    {
      "id": "deity_yaldabaoth",
      "type": "deity",
      "name": "亚达伯斯",
      "importance": 0.9,
      "properties": {
